DeltaIV30=(30)*((mean(of IV302)/sqrt(252))**2 - (mean(of IV30_2)/sqrt(252))**2);
RI30=(DeltaIV30 + SIGQP);
DeltaIV60=(60-2)*((mean(of IV602)/sqrt(252))**2 - (mean(of IV60_2)/sqrt(252))**2);
RI60=(DeltaIV60 + SIGQP);
DeltaIV122=(122)*((mean(of IV1222)/sqrt(252))**2 - (mean(of IV122_2)/sqrt(252))**2);
RI122=(DeltaIV122 + SIGQP);
DeltaIV182=(182)*((mean(of IV1822)/sqrt(252))**2 - (mean(of IV182_2)/sqrt(252))**2);
RI182=(DeltaIV182 + SIGQP);
DeltaIV365=(365)*((mean(of IV3652)/sqrt(252))**2 - (mean(of IV365_2)/sqrt(252))**2);
RI365=(DeltaIV365 + SIGQP);

	from SS3 A left outer join a.erp_public_210621 B
	on (A.GVKEY=B.GVKEY)
	& (1 eq intck('Month', A.ActDate, mdy(b.month, 1, b.year) ))
	order by A.Permno, A.ActDate;
quit;
proc sql;
	create table SS5 as
	select distinct A.*,
	100*(((1+B.GLS_an)**(12))-1) as GLS_1
	from SS4 A left outer join a.erp_public_210621 B
	on (A.GVKEY=B.GVKEY)
	& (1 eq intck('Month', mdy(b.month, 1, b.year), A.ActDate))
	order by A.Permno, A.ActDate;;
quit;

data SS6;
	set SS5;
	array testmiss(*) GLS1 GLS_1;
	do i=1 to dim(testmiss);
			if testmiss(i) lt 0 then testmiss(i)=.;
		end;
	drop i;
	DeltaGLS=(GLS1-GLS_1);
run;

proc univariate data =SSOPT(where=(&vname ne .)) noprint;
    by Period; var &vname;
    output out =S3 PCTLPTS =10 20 30 33 40 50 60 70 66 80 90 PCTLPRE = Cut PCTLNAME = _P10 _P20 _P30 _P33 _P40 _P50 _P60 _P66 _P70 _P80 _P90;
run; 
data S3B(drop=Period RepYear RepQtr);  set S3; 	
	RepYear=floor(Period/10);
	RepQtr=Period-(10*RepYear);
	if RepQtr le 3 then Period2=(RepYear*10)+(RepQtr+1);
	else Period2=((RepYear+1)*10)+(1);
run;
proc sort data=S3B out=S3C(rename=(Period2=Period)); by Period2; run;
data SSOPT(drop=Cut_P10 Cut_P20 Cut_P30 Cut_P33 Cut_P40 Cut_P50 Cut_P60 Cut_P66 Cut_P70 Cut_P80 Cut_P90);
	merge SSOPT(in=a) S3C(in=b); by Period; if a;

